#!/usr/bin/env python3
"""Generate contracts/test/FeeParity.t.sol from vectors/fees-v1.txt.

The contract's `quote` must return exactly what the Rust crate and the Python check return for
every vector, so all three implementations of the fee math are held to the same cases. Run this
after changing the vectors, and commit the result.
"""

import sys
from collections import OrderedDict

HEADER = """// SPDX-License-Identifier: MIT
pragma solidity 0.8.28;

// Generated by verifiers/python/gen_fee_parity.py from vectors/fees-v1.txt. Do not edit by hand.

import {SuriComAIEscrow} from "../src/SuriComAIEscrow.sol";
import {Fixture} from "./Fixture.sol";

/// @dev The contract's quote must equal the Rust and Python results for every shared vector.
contract FeeParityTest is Fixture {
    function _escrow(uint256 p, uint256 a, uint256 m, uint256 r) private returns (SuriComAIEscrow e) {
        SuriComAIEscrow.Config memory c = _config(address(usdc));
        c.protocolBps = p;
        c.attestationBps = a;
        c.attestationMin = m;
        c.relayBps = r;
        e = new SuriComAIEscrow(c);
    }

    function _same(SuriComAIEscrow e, uint128 price, uint256 protocol, uint256 att, uint256 relay, uint256 total)
        private
        view
    {
        SuriComAIEscrow.Quote memory q = e.quote(price);
        eq(q.price, price, "price");
        eq(q.protocol, protocol, "protocol");
        eq(q.attestation, att, "attestation");
        eq(q.relayMax, relay, "relay");
        eq(q.total, total, "total");
    }

    function _refused(SuriComAIEscrow e, uint128 price, bytes4 selector) private {
        vm.expectRevert(selector);
        e.quote(price);
    }
"""


def main(src, dst):
    groups = OrderedDict()
    for line in open(src):
        line = line.strip()
        if not line or line.startswith("#"):
            continue
        inputs, expected = line.split("|")
        p, a, m, r, price = (int(w) for w in inputs.split())
        groups.setdefault((p, a, m, r), []).append((price, expected.split()))
    out = [HEADER]
    for index, ((p, a, m, r), cases) in enumerate(groups.items()):
        out.append(f"\n    function test_schedule_{index}_matches_the_vectors() public {{")
        out.append(f"        SuriComAIEscrow e = _escrow({p}, {a}, {m}, {r});")
        for price, want in cases:
            if want == ["price_too_small"]:
                out.append(f"        _refused(e, {price}, SuriComAIEscrow.PriceTooSmall.selector);")
            elif want == ["fee_overflow"]:
                out.append(f"        _refused(e, {price}, SuriComAIEscrow.FeeOverflow.selector);")
            elif want == ["bad_fee_schedule"]:
                raise SystemExit("a vector names an invalid schedule")
            else:
                _, protocol, att, relay, total = want
                out.append(f"        _same(e, {price}, {protocol}, {att}, {relay}, {total});")
        out.append("    }")
    out.append("}")
    open(dst, "w").write("\n".join(out) + "\n")
    print(f"wrote {dst}: {len(groups)} schedules, {sum(len(c) for c in groups.values())} cases")


if __name__ == "__main__":
    main(
        sys.argv[1] if len(sys.argv) > 1 else "vectors/fees-v1.txt",
        sys.argv[2] if len(sys.argv) > 2 else "contracts/test/FeeParity.t.sol",
    )
